namespace PZ3D {
 static class JavaApprovalsTests {
  static readonly JavaScriptSerializer Json=new JavaScriptSerializer();
  static void Check(bool b,string reason){if(!b)throw new Exception("Java approval: "+reason);}
  static Type Api(){var t=typeof(Engine).Assembly.GetType("PZ3D.JavaApprovals");Check(t!=null,"individual approval backend exists");return t;}
  static Dictionary<string,object> Read(object o){return Json.Deserialize<Dictionary<string,object>>(Json.Serialize(o));}
  static Dictionary<string,object> List(Engine e){return Read(Api().GetMethod("List").Invoke(null,new object[]{e}));}
  static object Save(Engine e,Dictionary<string,object> list,string hash,bool decision){return Api().GetMethod("Save").Invoke(null,new object[]{e,(string)list["stamp"],hash,decision});}
  static Dictionary<string,object>[] Rows(Dictionary<string,object> list){return ((IEnumerable)list["jars"]).Cast<Dictionary<string,object>>().ToArray();}
  static void Reject(Action a,string reason){bool rejected=false;try{a();}catch(TargetInvocationException){rejected=true;}Check(rejected,reason);}
  sealed class Fixture {
   public string Root,Home,Approval,Jar;public Engine E;
   public Fixture(){Root=Path.Combine(LauncherTestPaths.Root,"java-"+Guid.NewGuid().ToString("N"));Home=Path.Combine(Root,"home");E=new Engine(Path.Combine(Root,"steamapps/common/ProjectZomboid"),Path.Combine(Root,"user"),Path.Combine(Root,"data"),true);Directory.CreateDirectory(E.Game);Directory.CreateDirectory(Path.GetDirectoryName(E.Mods));Directory.CreateDirectory(Path.Combine(Home,".zombie_buddy"));Approval=Path.Combine(Home,".zombie_buddy/mod_approvals.json");Config();File.WriteAllText(E.Mods,"VERSION = 1,\nmods\n{\n mod = ZombieBuddy,\n mod = Viewpoint,\n}\nmaps\n{\n}\n");string folder=Path.Combine(E.Workshop,"3809306528/mods/Viewpoint");Directory.CreateDirectory(Path.Combine(folder,"common"));Directory.CreateDirectory(Path.Combine(folder,"42/media/java/client"));File.WriteAllText(Path.Combine(folder,"common/mod.info"),"name=Fixture View\nid=Viewpoint\njavaJarFile=media/java/client/Viewpoint.jar\njavaPkgName=viewpoint\n");Jar=Path.Combine(folder,"42/media/java/client/Viewpoint.jar");File.WriteAllText(Jar,"abc",new UTF8Encoding(false));}
   public void Config(string extra=""){File.WriteAllText(E.Config,Json.Serialize(new{vmArgs=new[]{"-agentlib:zbNative","-Duser.home="+Home}.Concat(extra==""?new string[0]:new[]{extra}).ToArray()}));}
  }
  // These tests catch consent applied to wrong bytes, broad writes, stale approval,
  // ambiguous game resolution, and bypassed schema/process guards.
  public static int Main(string[] args){try{if(args.Contains("--inventory-budget")){InventoryBudget();return 0;}if(args.Contains("--native-path")){NativePathOverride();return 0;}Run();return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
  static Fixture LargeFixture(){var f=new Fixture();for(int i=0;i<665;i++){string folder=Path.Combine(f.E.User,"mods","Local"+i,"common");Directory.CreateDirectory(folder);File.WriteAllText(Path.Combine(folder,"mod.info"),"id=Local"+i+"\nname=Local fixture\n");}string[] ids={"ShootToThrillMultiplayer","LaoYuTranslationJava","OrangeShootPresentation"};string[] sources={Path.Combine(f.E.Workshop,"3813032735","mods"),Path.Combine(f.E.Workshop,"3810637496","mods"),Path.Combine(f.E.User,"mods")};for(int i=0;i<ids.Length;i++){string folder=Path.Combine(sources[i],ids[i]);Directory.CreateDirectory(Path.Combine(folder,"42","media","java","client"));File.WriteAllText(Path.Combine(folder,"42","mod.info"),"id="+ids[i]+"\njavaJarFile=media/java/client/"+ids[i]+".jar\njavaPkgName=fixture\n");File.WriteAllText(Path.Combine(folder,"42","media","java","client",ids[i]+".jar"),"synthetic-"+ids[i]);}return f;}
  static void InventoryBudget(){var f=LargeFixture();string single=File.ReadAllText(f.E.Mods),all=single.Replace(" mod = Viewpoint,"," mod = Viewpoint,\n mod = ShootToThrillMultiplayer,\n mod = LaoYuTranslationJava,\n mod = OrangeShootPresentation,");var one=new List<long>();var four=new List<long>();for(int i=0;i<4;i++){File.WriteAllText(f.E.Mods,single);var timer=Stopwatch.StartNew();var list=List(f.E);timer.Stop();Check((bool)list["supported"]&&Rows(list).Length==1,"large single-component inventory supported");if(i>0)one.Add(timer.ElapsedMilliseconds);File.WriteAllText(f.E.Mods,all);timer.Restart();list=List(f.E);timer.Stop();Check((bool)list["supported"]&&Rows(list).Length==4,"large four-component inventory supported");if(i>0)four.Add(timer.ElapsedMilliseconds);}one.Sort();four.Sort();Console.WriteLine("JAVA INVENTORY 665 LOCAL MODS: single="+one[1]+"ms, four="+four[1]+"ms");var initial=List(f.E);var sw=Stopwatch.StartNew();var saved=Read(Save(f.E,initial,(string)Rows(initial)[0]["sha256"],true));sw.Stop();Check((bool)saved["supported"]&&Rows(saved)[0]["decision"].Equals(true),"large save returns persisted decision");Console.WriteLine("JAVA APPROVAL SAVE 665 LOCAL MODS / 4 COMPONENTS: "+sw.ElapsedMilliseconds+"ms");Check(four[1]<=one[1]*2.5,"adding managed components must not repeat the 665-folder inventory for each component");}
  public static void Run(){
   NativePathOverride();
   ScopedSteam();
   var f=new Fixture();var l=List(f.E);Check((bool)l["supported"],"isolated effective Java home supported");var r=Rows(l);Check(r.Length==1&&r[0]["id"].Equals("Viewpoint")&&r[0]["workshopId"].Equals("3809306528"),"enabled managed jar discovered from common metadata and version binary");Check(r[0]["sha256"].Equals("ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"),"full original bytes hashed in lowercase SHA256");Check(r[0]["decision"]==null&&!File.Exists(f.Approval),"listing never creates approval or implies consent");
   File.WriteAllText(f.Approval,"{\"formatVersion\":2,\"extension\":{\"retain\":true},\"mods\":[{\"id\":\"Other\",\"jar_hash\":\""+new string('1',64)+"\",\"decision\":false,\"author_id\":76561198043849998,\"extra\":\"keep\"}]}");string trust=Path.Combine(Path.GetDirectoryName(f.Approval),"config.json");File.WriteAllText(trust,"{\"trusted_authors\":[76561198043849998],\"opaque\":true}");string beforeTrust=File.ReadAllText(trust);l=List(f.E);string h=(string)Rows(l)[0]["sha256"];var approved=Read(Save(f.E,l,h,true));Check((bool)approved["supported"]&&Rows(approved)[0]["decision"].Equals(true),"save returns authoritative newly persisted approval without another list request");Check(!approved["stamp"].Equals(l["stamp"])&&approved["stamp"].Equals(List(f.E)["stamp"]),"save returns fresh snapshot stamp matching persisted state");var stored=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(f.Approval));var mods=((IEnumerable)stored["mods"]).Cast<Dictionary<string,object>>().ToArray();Check(mods.Length==2&&(bool)mods[1]["decision"]&&mods[1]["jar_hash"].Equals(h),"explicit one-hash approval persisted");Check(mods[0]["author_id"].ToString()=="76561198043849998"&&mods[0]["extra"].Equals("keep")&&stored.ContainsKey("extension"),"unknown fields and 64-bit IDs preserved");Check(File.ReadAllText(trust)==beforeTrust&&!mods[1].ContainsKey("author_id"),"author trust untouched and signer never invented");Check(Rows(List(f.E))[0]["decision"].Equals(true),"persisted decision shown");l=List(f.E);Save(f.E,l,h,false);Check(Rows(List(f.E))[0]["decision"].Equals(false),"individual denial updates chosen hash");
   l=List(f.E);string saved=File.ReadAllText(f.Approval);File.WriteAllText(f.Jar,"changed");Reject(()=>Save(f.E,l,h,true),"changed bytes reject stale consent");Check(File.ReadAllText(f.Approval)==saved,"stale file leaves decisions untouched");l=List(f.E);File.AppendAllText(f.Approval," ");Reject(()=>Save(f.E,l,(string)Rows(l)[0]["sha256"],true),"external approval change invalidates snapshot");
   var metadataChange=new Fixture();var metadataList=List(metadataChange.E);File.AppendAllText(Path.Combine(metadataChange.E.Workshop,"3809306528/mods/Viewpoint/common/mod.info"),"author=changed fixture\n");Reject(()=>Save(metadataChange.E,metadataList,(string)Rows(metadataList)[0]["sha256"],true),"changed metadata rejects stale snapshot");Check(!File.Exists(metadataChange.Approval),"changed metadata leaves absent approval store untouched");
   var newSource=new Fixture();var sourceList=List(newSource.E);string source=Path.Combine(newSource.E.User,"mods/Added/common");Directory.CreateDirectory(source);File.WriteAllText(Path.Combine(source,"mod.info"),"id=UnrelatedFixture\n");Reject(()=>Save(newSource.E,sourceList,(string)Rows(sourceList)[0]["sha256"],true),"changed source inventory rejects stale snapshot");Check(!File.Exists(newSource.Approval),"changed inventory leaves absent approval store untouched");
   foreach(string bad in new[]{"{}","{\"formatVersion\":3,\"mods\":[]}","{\"formatVersion\":2,\"mods\":[{\"jar_hash\":\"bad\",\"decision\":true}]}","{\"formatVersion\":2,\"mods\":[{\"jar_hash\":\""+new string('a',64)+"\",\"decision\":true},{\"jar_hash\":\""+new string('a',64)+"\",\"decision\":false}]}","not-json"}){var b=new Fixture();File.WriteAllText(b.Approval,bad);Check(!(bool)List(b.E)["supported"],"malformed/unknown/conflicting approvals refused");Check(File.ReadAllText(b.Approval)==bad,"read-only schema failure");}
   var pending=new Fixture();Directory.CreateDirectory(Path.Combine(pending.E.Data,"launch-sessions"));File.WriteAllText(Path.Combine(pending.E.Data,"launch-sessions",LaunchProfiles.Key(pending.E)+".json"),"{}");Check(!(bool)List(pending.E)["supported"],"pending profile switch prevents consent");
   var overrideF=new Fixture();overrideF.Config("-Duser.home="+Path.Combine(overrideF.Root,"another"));Check(!(bool)List(overrideF.E)["supported"],"conflicting Java homes refused");var agent=new Fixture();string dir=Path.Combine(agent.Root,"config");File.WriteAllText(agent.E.Config,Json.Serialize(new{vmArgs=new[]{"-agentlib:zbNative=config_dir="+dir}}));var al=List(agent.E);Save(agent.E,al,(string)Rows(al)[0]["sha256"],true);Check(File.Exists(Path.Combine(dir,"mod_approvals.json"))&&!File.Exists(agent.Approval),"official agent config_dir receives isolated decision");
   var shadow=new Fixture();string shadowDir=Path.Combine(shadow.E.User,"mods/Shadow/common");Directory.CreateDirectory(shadowDir);File.WriteAllText(Path.Combine(shadowDir,"mod.info"),"id=Viewpoint\n");Check(!(bool)List(shadow.E)["supported"],"local duplicate identity refuses unknown game override");
   var addon=new Fixture();File.WriteAllText(addon.E.Mods,"mods\n{\n mod = ViewpointSurface,\n}\n");string addonFolder=Path.Combine(addon.E.Workshop,"3814398576/mods/ViewpointSurface");Directory.CreateDirectory(Path.Combine(addonFolder,"common"));Directory.CreateDirectory(Path.Combine(addonFolder,"42/media/java/client"));File.WriteAllText(Path.Combine(addonFolder,"common/mod.info"),"id=ViewpointSurface\njavaJarFile=media/java/client/Surface.jar\njavaPkgName=surface\n");File.WriteAllText(Path.Combine(addonFolder,"42/mod.info"),"id=ViewpointSurface\n");File.WriteAllText(Path.Combine(addonFolder,"42/media/java/client/Surface.jar"),"isolated-addon");var addonList=List(addon.E);Check((bool)addonList["supported"]&&Rows(addonList).Length==1&&Rows(addonList)[0]["id"].Equals("ViewpointSurface"),"same addon identity in common and 42 is one source");var addonApproved=Read(Save(addon.E,addonList,(string)Rows(addonList)[0]["sha256"],true));Check(Rows(addonApproved)[0]["decision"].Equals(true),"addon-only capture returns exact persisted approval");string duplicate=Path.Combine(addon.E.User,"mods/AddonShadow/common");Directory.CreateDirectory(duplicate);File.WriteAllText(Path.Combine(duplicate,"mod.info"),"id=ViewpointSurface\n");Check(!(bool)List(addon.E)["supported"],"addon duplicate identity still refuses unknown source");
   var escape=new Fixture();string info=Path.Combine(escape.E.Workshop,"3809306528/mods/Viewpoint/common/mod.info");File.WriteAllText(info,"id=Viewpoint\njavaJarFile=../../../../escape.jar\njavaPkgName=viewpoint\n");Check(!(bool)List(escape.E)["supported"],"escaped Java path refused");
   var inactive=new Fixture();File.WriteAllText(inactive.E.Mods,"mods\n{\n mod = Other,\n}\n");Check(Rows(List(inactive.E)).Length==0,"inactive managed component excluded");
   var mixed=new Fixture();File.WriteAllText(Path.Combine(mixed.E.Workshop,"3809306528/mods/Viewpoint/42/mod.info"),"id=OtherMod\njavaJarFile=media/java/client/Viewpoint.jar\njavaPkgName=other\n");Check(!(bool)List(mixed.E)["supported"],"conflicting version/common identity never authorizes another mod binary");
   var unknownHome=new Fixture();File.WriteAllText(unknownHome.E.Config,"{\"vmArgs\":[\"-agentlib:zbNative\"]}");Check(!(bool)List(unknownHome.E)["supported"],"default Java home is never guessed when bundled Java is absent");
   var unknownOption=new Fixture();File.WriteAllText(unknownOption.E.Config,Json.Serialize(new{vmArgs=new[]{"-agentlib:zbNative=custom_dir=secret","-Duser.home="+unknownOption.Home}}));Check(!(bool)List(unknownOption.E)["supported"],"unknown native Buddy directory options never authorize guessed home");
   Check(BuddyLaunchArguments.HasAuthorizationOverride("-Duser.home=E:\\other"),"Steam user.home override cannot silently approve wrong store");Check(!BuddyLaunchArguments.HasAuthorizationOverride("-nosteam"),"ordinary Steam launch options need no directory refusal");
   Console.WriteLine("JAVA APPROVAL TESTS PASSED; isolated fixtures retained under E:/AppCaches/OrangeLauncherProfiles/TestFixtures");
  }
  static void NativePathOverride(){
   foreach(bool branch in new[]{false,true}){var f=new Fixture();string native="-agentpath:C:\\mods\\zbNative.dll=config_dir=C:\\other";var root=new Dictionary<string,object>{{"vmArgs",new[]{"-agentlib:zbNative","-Duser.home="+f.Home}.Concat(branch?new string[0]:new[]{native}).ToArray()}};if(branch)root["windows"]=new Dictionary<string,object>{{"10",new Dictionary<string,object>{{"vmArgs",new[]{native}}}}};File.WriteAllText(f.E.Config,Json.Serialize(root));Check(!(bool)List(f.E)["supported"],"unknown native agentpath in "+(branch?"effective Windows branch":"root")+" refuses actual Java authorization");Check(!File.Exists(f.Approval),"unknown agentpath creates no approval");}
   var supported=new Fixture();string directory=Path.Combine(supported.Root,"resolved");File.WriteAllText(supported.E.Config,Json.Serialize(new{vmArgs=new[]{"-agentlib:zbNative=config_dir="+directory}}));Check((bool)List(supported.E)["supported"],"supported resolved JSON config_dir remains usable");
  }
  static void ScopedSteam(){
   var fixture=new Fixture();string steam=Path.Combine(fixture.Root,"client");var e=new Engine(fixture.E.Game,fixture.E.User,fixture.E.Data,true,()=>SteamLaunchOptions.Read(steam,42));
   SteamLaunchOptionsTests.Fixture(steam,42,SteamLaunchOptionsTests.Wrap("\"999\" { \"LaunchOptions\" \"-javaagent:ZombieBuddy.jar -Duser.home=private\" } \"108600\" { \"LaunchOptions\" \"-nosteam\" }"));SteamLaunchOptionsTests.Fixture(steam,7,SteamLaunchOptionsTests.Wrap("\"108600\" { \"LaunchOptions\" \"-Duser.home=private\" }"));var before=List(e);Check((bool)before["supported"],"another account and app cannot block current Java approval");
   SteamLaunchOptionsTests.Fixture(steam,42,SteamLaunchOptionsTests.Wrap("\"108600\" { \"LaunchOptions\" \"-Duser.home=private\" }"));Check(!(bool)List(e)["supported"],"actual own unknown Steam user.home still refuses approval");
   SteamLaunchOptionsTests.Fixture(steam,42,SteamLaunchOptionsTests.Wrap("\"108600\" { \"LaunchOptions\" \"-Dconfig_dir=private\" }"));Check(!(bool)List(e)["supported"],"actual own config_dir still refuses approval");
   SteamLaunchOptionsTests.Fixture(steam,42,SteamLaunchOptionsTests.Wrap("\"108600\" { \"LaunchOptions\" \"-nosteam -debug\" }"));var next=List(e);Check((bool)next["supported"]&&!before["stamp"].Equals(next["stamp"]),"approval stamp includes own bounded launch options");Check(!File.Exists(fixture.Approval),"scoped checks never auto-authorize Java");
  }
